#include <bits/stdc++.h>
using namespace std;

class Solution {
 long long gcd(long long a,long long b){while(b){long long t=a%b;a=b;b=t;}return a;}
 public:
 vector<int> replaceNonCoprimes(vector<int>& nums){vector<long long> st;
  for(int x:nums){long long v=x;while(!st.empty()){
    long long g=gcd(st.back(),v);if(g==1)break;v=st.back()/g*v;st.pop_back();
   }st.push_back(v);
  }return vector<int>(st.begin(),st.end());
 }
};
